  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 16→import './App.css';
 17→
 18→function findDuplicateFileNames(files: File[]): string[] {
 19→  const seen = new Set<string>();
 20→  const duplicates = new Set<string>();
 21→  for (const file of files) {
 22→    if (seen.has(file.name)) {
 23→      duplicates.add(file.name);
 24→    }
 25→    seen.add(file.name);
 26→  }
 27→  return Array.from(duplicates);
 28→}
