318→export default function App() {
319→  const [tables, setTables] = useState<TableInfo[]>([]);
320→  const [loading, setLoading] = useState(true);
321→  const [error, setError] = useState<string | null>(null);
322→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
323→
324→  const refreshTables = useCallback(async () => {
325→    try {
326→      const response = await fetch('/api/tables');
327→      if (!response.ok) throw new Error('Failed to fetch tables');
328→      const data = await response.json();
329→      setTables(data);
330→    } catch (e) {
331→      console.error('Failed to refresh tables:', e);
332→    }
333→  }, []);
334→
335→  useEffect(() => {
336→    (async () => {
337→      try {
338→        const response = await fetch('/api/health');
339→        if (!response.ok) throw new Error('Backend is not available');
340→        await refreshTables();
341→        try {
342→          const lfRes = await fetch('/api/langfuse/status');
343→          if (lfRes.ok) {
344→            setLangfuseStatus(await lfRes.json());
345→          }
346→        } catch {
347→          // Langfuse status fetch is non-critical
348→        }
349→      } catch (e) {
350→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
351→      } finally {
352→        setLoading(false);
353→      }
354→    })();
355→  }, [refreshTables]);
356→
357→  if (loading) {
358→    return <div className="app-loading">Connecting to backend...</div>;
359→  }
360→
361→  if (error) {
362→    return (
363→      <div className="app-error">Failed to connect: {error}</div>
364→    );
365→  }
366→
367→  return (
368→    <ConfigProvider>
369→      <LanguageProvider>
370→        <ThemeProvider>
371→          <AgentProvider refreshTables={refreshTables}>
372→            <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
373→          </AgentProvider>
374→        </ThemeProvider>
375→      </LanguageProvider>
376→    </ConfigProvider>
377→  );
378→}
