 1→import { createContext, useContext } from 'react';
 2→
 3→export type Language = 'en' | 'zh-TW';
 4→
 5→interface LanguageContextValue {
 6→  language: Language;
 7→  setLanguage: (lang: Language) => void;
 8→  t: (key: string, params?: Record<string, string | number>) => string;
 9→}
10→
11→export const LanguageContext = createContext<LanguageContextValue | null>(null);
12→
13→export function useTranslation() {
14→  const ctx = useContext(LanguageContext);
15→  if (!ctx) throw new Error('useTranslation must be used within LanguageProvider');
16→  return ctx;
17→}
