  1→import type { ToolCallResult } from '../types';
  2→
  3→interface AgentCallbacks {
  4→  onTextChunk: (text: string) => void;
  5→  onThinkingDone: () => void;
  6→  onToolCall: (pending: ToolCallResult) => void;
  7→  onToolResult: (result: ToolCallResult) => void;
  8→  onDone: (sessionId: string | null) => void;
  9→  onError: (error: string) => void;
 10→}
 11→
 12→export type { AgentCallbacks };
 13→
 14→async function streamSSE(
 15→  response: Response,
 16→  callbacks: AgentCallbacks,
 17→  signal?: AbortSignal,
 18→): Promise<void> {
 19→  const reader = response.body?.getReader();
 20→  if (!reader) {
 21→    callbacks.onError('No response stream');
 22→    return;
 23→  }
 24→
 25→  try {
 26→    const decoder = new TextDecoder();
 27→    let buffer = '';
 28→
 29→    while (true) {
 30→      const { done, value } = await reader.read();
 31→      if (done) break;
 32→
 33→      buffer += decoder.decode(value, { stream: true });
 34→      const lines = buffer.split('\n');
 35→      buffer = lines.pop() ?? '';
 36→
 37→      let eventType = '';
 38→      for (const line of lines) {
 39→        if (line.startsWith('event: ')) {
 40→          eventType = line.slice(7).trim();
 41→        } else if (line.startsWith('data: ')) {
 42→          const data = line.slice(6);
 43→          try {
 44→            const parsed = JSON.parse(data);
 45→            handleSSEEvent(eventType, parsed, callbacks);
 46→          } catch {
 47→            // Skip malformed JSON
 48→          }
 49→          eventType = '';
 50→        }
 51→      }
 52→    }
 53→  } catch (e: unknown) {
 54→    if (signal?.aborted) return;
 55→    const msg = e instanceof Error ? e.message : 'Connection failed';
 56→    callbacks.onError(msg);
 57→  }
 58→}
 59→
 60→export async function runAgentLoop(
 61→  message: string,
 62→  sessionId: string | null,
 63→  callbacks: AgentCallbacks,
 64→  signal?: AbortSignal,
 65→): Promise<void> {
 66→  try {
 67→    const response = await fetch('/api/chat', {
 68→      method: 'POST',
 69→      headers: { 'Content-Type': 'application/json' },
 70→      body: JSON.stringify({ message, session_id: sessionId }),
 71→      signal,
 72→    });
 73→
 74→    if (!response.ok) {
 75→      const errorText = await response.text();
 76→      callbacks.onError(`Server error: ${errorText}`);
 77→      return;
 78→    }
 79→
 80→    await streamSSE(response, callbacks, signal);
 81→  } catch (e: unknown) {
 82→    if (signal?.aborted) return;
 83→    const msg = e instanceof Error ? e.message : 'Connection failed';
 84→    callbacks.onError(msg);
 85→  }
 86→}
 87→
 88→export async function runAgentEditLoop(
 89→  newMessage: string,
 90→  conversationHistory: { role: string; content: string }[],
 91→  callbacks: AgentCallbacks,
 92→  signal?: AbortSignal,
 93→): Promise<void> {
 94→  try {
 95→    const response = await fetch('/api/chat/edit', {
 96→      method: 'POST',
 97→      headers: { 'Content-Type': 'application/json' },
 98→      body: JSON.stringify({
 99→        new_message: newMessage,
100→        conversation_history: conversationHistory,
101→      }),
102→      signal,
103→    });
104→
105→    if (!response.ok) {
106→      const errorText = await response.text();
107→      callbacks.onError(`Server error: ${errorText}`);
108→      return;
109→    }
110→
111→    await streamSSE(response, callbacks, signal);
112→  } catch (e: unknown) {
113→    if (signal?.aborted) return;
114→    const msg = e instanceof Error ? e.message : 'Connection failed';
115→    callbacks.onError(msg);
116→  }
117→}
118→
119→function handleSSEEvent(
120→  eventType: string,
121→  data: Record<string, unknown>,
122→  callbacks: AgentCallbacks,
123→) {
124→  switch (eventType) {
125→    case 'thinking':
126→    case 'answer':
127→      callbacks.onTextChunk(data.text as string);
128→      break;
129→    case 'thinking_done':
130→      callbacks.onThinkingDone();
131→      break;
132→    case 'tool_call':
133→      callbacks.onToolCall({
134→        toolCallId: (data.id as string) ?? '',
135→        toolName: (data.name as string) ?? undefined,
136→        sql: (data.sql as string) ?? '',
137→        command: (data.command as string) ?? undefined,
138→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
139→        columns: [],
140→        rows: [],
141→        rowCount: 0,
142→      });
143→      break;
144→    case 'tool_result': {
145→      const result: ToolCallResult = {
146→        toolCallId: (data.id as string) ?? '',
147→        toolName: (data.name as string) ?? undefined,
148→        sql: (data.sql as string) ?? '',
149→        columns: (data.columns as string[]) ?? [],
150→        rows: (data.rows as Record<string, unknown>[]) ?? [],
151→        rowCount: (data.rowCount as number) ?? 0,
152→        error: (data.error as string) ?? undefined,
153→        output: (data.output as string) ?? undefined,
154→        rawContent: (data.content as string) ?? undefined,
155→      };
156→      callbacks.onToolResult(result);
157→      break;
158→    }
159→    case 'done':
160→      callbacks.onDone((data.session_id as string) ?? null);
161→      break;
162→    case 'error':
163→      callbacks.onError((data.message as string) ?? 'Unknown error');
164→      break;
165→  }
166→}
