 10→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 11→  // Use streaming remainder if available
 12→  if (streamingRemainder?.trim()) {
 13→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 14→    const last = lines[lines.length - 1] || '';
 15→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 16→  }
 17→  // Otherwise use last thinking segment's last line
 18→  for (let i = segments.length - 1; i >= 0; i--) {
 19→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 20→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 21→      const last = lines[lines.length - 1] || '';
 22→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 23→    }
 24→  }
 25→  return t('thinking');
 26→}
 27→
 28→function ThinkingBlock({ segments, streamingRemainder, isActivelyStreaming }: {
 29→  segments: ContentSegment[];
 30→  streamingRemainder?: string;
 31→  isActivelyStreaming: boolean;
 32→}) {
 33→  const { t } = useTranslation();
 34→  // All non-answer segments go inside the thinking block
 35→  const thinkingSegments = segments.filter((s) => s.type !== 'answer');
 36→  const hasContent = thinkingSegments.some(
 37→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult)
 38→  ) || streamingRemainder?.trim();
 39→
 40→  if (!hasContent) return null;
 41→
 42→  const summary = getLastThinkingLine(segments, streamingRemainder, t);
 43→
 44→  return (
 45→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isActivelyStreaming || undefined}>
 46→      <summary className="message-bubble__collapsible-summary">
 47→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 48→        <span className="message-bubble__collapsible-preview">{summary}</span>
 49→      </summary>
 50→      <div className="message-bubble__thinking-body">
 51→        {thinkingSegments.map((seg, i) => {
 52→          if (seg.type === 'thinking' && seg.text?.trim()) {
 53→            return (
 54→              <div key={i} className="message-bubble__segment-content">
 55→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 56→              </div>
 57→            );
 58→          }
 59→          if (seg.type === 'tool' && seg.toolResult) {
