 78→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
 79→  const { t } = useTranslation();
 80→  const { isStreaming, editMessage, deleteMessage } = useAgent();
 81→  const [isEditing, setIsEditing] = useState(false);
 82→  const [editText, setEditText] = useState(message.content);
 83→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
 84→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 85→
 86→  const isUser = message.role === 'user';
 87→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
 88→
 89→  useEffect(() => {
 90→    if (isEditing && textareaRef.current) {
 91→      textareaRef.current.focus();
 92→      textareaRef.current.selectionStart = textareaRef.current.value.length;
 93→    }
 94→  }, [isEditing]);
 95→
 96→  const handleEdit = () => {
 97→    setEditText(message.content);
 98→    setIsEditing(true);
 99→    setIsConfirmingDelete(false);
100→  };
101→
102→  const handleCancelEdit = () => {
103→    setIsEditing(false);
104→    setEditText(message.content);
105→  };
106→
107→  const handleSaveEdit = () => {
108→    const trimmed = editText.trim();
109→    if (!trimmed || trimmed === message.content) {
110→      handleCancelEdit();
111→      return;
112→    }
113→    setIsEditing(false);
114→    editMessage(messageIndex, trimmed);
115→  };
116→
117→  const handleDeleteConfirm = () => {
118→    setIsConfirmingDelete(false);
119→    deleteMessage(messageIndex);
120→  };
121→
122→  const handleKeyDown = (e: React.KeyboardEvent) => {
123→    if (e.key === 'Escape') {
124→      handleCancelEdit();
125→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
126→      e.preventDefault();
127→      handleSaveEdit();
128→    }
129→  };
130→
131→  let streamingRemainder: string | undefined;
132→  if (hasSegments && message.isStreaming && message.content) {
133→    const segmentedText = message.segments!
134→      .filter((s) => s.type !== 'tool')
135→      .map((s) => s.text || '')
136→      .join('');
137→    const remaining = message.content.slice(segmentedText.length);
138→    if (remaining.trim()) {
139→      streamingRemainder = remaining;
140→    }
141→  }
142→
143→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
144→  const isInAnswerPhase = message.currentPhase === 'answer';
145→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
146→
147→  const answerSegments = hasSegments
148→    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
149→    : [];
150→
151→  return (
152→    <div className={`message-bubble message-bubble--${message.role}`}>
153→      <div className="message-bubble__header">
154→        {isUser ? t('you') : t('assistant')}
155→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
156→          <span className="message-bubble__actions">
157→            <button
158→              className="message-bubble__action-btn"
159→              onClick={handleEdit}
160→              title={t('editMessage')}
161→            >
162→              &#9998;
163→            </button>
164→            <button
165→              className="message-bubble__action-btn message-bubble__action-btn--delete"
166→              onClick={() => setIsConfirmingDelete(true)}
167→              title={t('deleteMessage')}
168→            >
169→              &#128465;
170→            </button>
171→          </span>
172→        )}
173→      </div>
174→
175→      {isUser && isConfirmingDelete && (
176→        <div className="message-bubble__confirm-delete">
177→          <span>{t('deleteConfirm')}</span>
178→          <div className="message-bubble__confirm-actions">
179→            <button
180→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
181→              onClick={handleDeleteConfirm}
182→            >
183→              {t('delete')}
184→            </button>
185→            <button
186→              className="message-bubble__confirm-btn"
187→              onClick={() => setIsConfirmingDelete(false)}
188→            >
189→              {t('cancel')}
190→            </button>
191→          </div>
192→        </div>
193→      )}
194→
195→      {isUser && isEditing ? (
196→        <div className="message-bubble__edit-mode">
197→          <textarea
198→            ref={textareaRef}
199→            className="message-bubble__edit-textarea"
200→            value={editText}
201→            onChange={(e) => setEditText(e.target.value)}
202→            onKeyDown={handleKeyDown}
203→            rows={3}
204→          />
205→          <div className="message-bubble__edit-actions">
206→            <button
207→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
208→              onClick={handleSaveEdit}
209→            >
210→              {t('saveResend')}
211→            </button>
212→            <button
213→              className="message-bubble__edit-btn"
214→              onClick={handleCancelEdit}
215→            >
216→              {t('cancel')}
217→            </button>
218→          </div>
219→        </div>
220→      ) : hasSegments ? (
221→        <div className="message-bubble__segments">
222→          <ThinkingBlock
223→            segments={message.segments!}
224→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
225→            isActivelyStreaming={isThinkingPhase}
226→          />
227→          {answerSegments.map((seg, i) => (
228→            <div key={i} className="message-bubble__segment message-bubble__segment--answer">
229→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
230→              <div className="message-bubble__segment-content">
231→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
232→              </div>
233→            </div>
234→          ))}
235→          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (
236→            <div className="message-bubble__segment message-bubble__segment--answer">
237→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
238→              <div className="message-bubble__segment-content">
239→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
240→              </div>
241→            </div>
242→          )}
243→          {message.isStreaming && !message.content && (
244→            <span className="message-bubble__typing">{t('thinking')}</span>
245→          )}
246→        </div>
247→      ) : (
248→        <>
249→          <div className="message-bubble__content">
250→            {message.content ? (
251→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
252→            ) : message.isStreaming ? (
253→              <span className="message-bubble__typing">{t('thinking')}</span>
254→            ) : null}
255→          </div>
256→          {message.toolCalls && message.toolCalls.length > 0 && (
257→            <div className="message-bubble__tools">
258→              {message.toolCalls.map((tc) => (
259→                <InlineQueryResult key={tc.toolCallId} result={tc} />
260→              ))}
261→            </div>
262→          )}
263→        </>
264→      )}
265→    </div>
266→  );
267→}
