10→  const textareaRef = useRef<HTMLTextAreaElement>(null);
11→
12→  const handleSend = () => {
13→    const trimmed = text.trim();
14→    if (!trimmed || isStreaming) return;
15→    sendMessage(trimmed);
16→    setText('');
17→    if (textareaRef.current) {
18→      textareaRef.current.style.height = 'auto';
