**Language Context** (in `/Users/cyyeh/Desktop/duckdb-data-agent/frontend/src/contexts/LanguageContext.tsx`):
```typescript
export type Language = 'en' | 'zh-TW';

interface LanguageContextValue {
  language: Language;
